const resolveComment = `-- name: ResolveComment :one
UPDATE comment SET resolved_at = clock_timestamp(), resolved_by = $1, rev = rev + 1
WHERE workspace_id = $2 AND project_id = $3 AND id = $4 AND parent_id IS NULL
    AND resolved_at IS NULL
RETURNING rev
`

type ResolveCommentParams struct {
	ResolvedBy  pgtype.UUID
	WorkspaceID pgtype.UUID
	ProjectID   pgtype.UUID
	ID          pgtype.UUID
}

// ResolveComment resolves the thread of the root, as resolved_by, unless it
// is resolved already, and returns the root's new revision, or no row if it
// is. It is resolved as the server's clock has it as the batch applies, as
// InsertComment posts a comment, so that a thread resolved in the batch that
// started it is not resolved before it was started.
func (q *Queries) ResolveComment(ctx context.Context, arg ResolveCommentParams) (int64, error) {
	row := q.db.QueryRow(ctx, resolveComment,
		arg.ResolvedBy,
		arg.WorkspaceID,
		arg.ProjectID,
		arg.ID,
	)
	var rev int64
	err := row.Scan(&rev)
	return rev, err
}

const restoreComment = `-- name: RestoreComment :one
UPDATE comment SET deleted_at = NULL, rev = rev + 1
WHERE workspace_id = $1 AND project_id = $2 AND id = $3 AND deleted_at IS NOT NULL
RETURNING rev
`

type RestoreCommentParams struct {
	WorkspaceID pgtype.UUID
	ProjectID   pgtype.UUID
	ID          pgtype.UUID
}

// RestoreComment takes the comment out of the project's trash, unless it is
// not there, and returns its new revision, or no row if it is not.
func (q *Queries) RestoreComment(ctx context.Context, arg RestoreCommentParams) (int64, error) {
	row := q.db.QueryRow(ctx, restoreComment, arg.WorkspaceID, arg.ProjectID, arg.ID)
	var rev int64
	err := row.Scan(&rev)
	return rev, err
}

const trashComment = `-- name: TrashComment :one
UPDATE comment SET deleted_at = clock_timestamp(), rev = rev + 1
WHERE workspace_id = $1 AND project_id = $2 AND id = $3 AND deleted_at IS NULL
RETURNING rev
`

type TrashCommentParams struct {
	WorkspaceID pgtype.UUID
	ProjectID   pgtype.UUID
	ID          pgtype.UUID
}

// TrashComment deletes the comment to the project's trash, unless it is
// there already, and returns its new revision, or no row if it is. It leaves
// when the comment last changed, and when it was edited, as they were, as
// RestoreComment does, since neither changes its body: a comment restored by
// the undo of its deletion is shown as it was before. It is deleted as the
// server's clock has it as the batch applies, as InsertComment posts a
// comment, so that a comment deleted in the batch that posted it is not
// deleted before it was posted.
func (q *Queries) TrashComment(ctx context.Context, arg TrashCommentParams) (int64, error) {
	row := q.db.QueryRow(ctx, trashComment, arg.WorkspaceID, arg.ProjectID, arg.ID)
	var rev int64
	err := row.Scan(&rev)
	return rev, err
}

const unresolveComment = `-- name: UnresolveComment :one
UPDATE comment SET resolved_at = NULL, resolved_by = NULL, rev = rev + 1
WHERE workspace_id = $1 AND project_id = $2 AND id = $3 AND resolved_at IS NOT NULL
RETURNING rev
`

type UnresolveCommentParams struct {
	WorkspaceID pgtype.UUID
	ProjectID   pgtype.UUID
	ID          pgtype.UUID
}

// UnresolveComment opens the thread of the root again, unless it is open
// already, and returns the root's new revision, or no row if it is.
func (q *Queries) UnresolveComment(ctx context.Context, arg UnresolveCommentParams) (int64, error) {
	row := q.db.QueryRow(ctx, unresolveComment, arg.WorkspaceID, arg.ProjectID, arg.ID)
	var rev int64
	err := row.Scan(&rev)
	return rev, err
}
